// components/Navbar.js
import { useTab } from '../context/TabContext';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const { changeTab } = useTab(); // ✅ Используем контекст
  const { user, cart } = useAuth();

  // Виджет корзины
  const CartWidget = () => (
    <div 
      className="relative cursor-pointer"
      onClick={() => {
        changeTab('cart'); // ✅ Теперь это меняет вкладку в Profile
        window.location.hash = 'profile?tab=cart'; // ✅ Навигация на страницу профиля
      }}
    >
      <span>🛒</span>
      {cart.length > 0 && (
        <span className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-5 h-5 text-xs flex items-center justify-center">
          {cart.length}
        </span>
      )}
    </div>
  );

  // Виджет избранного
  const FavoritesWidget = () => (
    <div 
      className="cursor-pointer"
      onClick={() => {
        changeTab('favorites');
        window.location.hash = 'profile?tab=favorites';
      }}
    >
      ❤️
    </div>
  );

  return (
    <nav className="flex justify-between items-center p-4 bg-white shadow-md">
      {/* Лого и другие элементы */}
      <div>Логотип</div>

      {user && (
        <div className="flex items-center space-x-4">
          <FavoritesWidget />
          <CartWidget />
          {/* Другие виджеты */}
        </div>
      )}
    </nav>
  );
};

export default Navbar;
